type MatchClassification = 'strong' | 'potential' | 'weak' | 'insufficient_data';
type AiMatch = { id: string; classification: MatchClassification; result: { summary: string; requirements: Array<{ status: string; requirement: string; importance: string; evidenceIds: string[]; explanation: string }>; eligibility: Array<{ criterion: string; status: string; explanation: string }>; strengths: string[]; gaps: string[]; recommendations: string[] }; status: string; model: string; completed_at: string; outdated: boolean };
type AiConnection = { id: string; provider_type: string; display_name: string; base_url: string | null; model: string; max_output_tokens: number; timeout_ms: number; enabled: boolean; api_key_configured: boolean; profile_consent_at: string | null };
type AiSettings = { default_connection_id: string | null; default_model: string | null };
type ProfileSummary = { configured: true; source: 'uploaded' | 'file'; profile_id: string; evidence_count: number; hash: string } | { configured: false };
type Tag = { id: string; name: string; color: string; created_at: string; updated_at: string };
type GroupBy = '' | 'tag' | 'company' | 'location' | 'source' | 'month';
type SortBy = 'newest' | 'oldest' | 'updated' | 'company' | 'location' | 'title' | 'waiting';
type Job = { id: string; title: string | null; company: string | null; location: string | null; source: string; source_url: string; status: Status; interview_stage: InterviewStage | null; notes: string; employment_type: string | null; workplace_type: string | null; description_html: string | null; created_at: string; captured_at: string; parse_status: string; last_event_at: string; tags: Tag[]; events?: JobEvent[]; ai_match?: AiMatch | null };
const stages: Array<{ status: Exclude<Status, 'archived'>; label: string; next?: Status; nextLabel?: string }> = [{ status: 'saved', label: 'Сохранено', next: 'sent', nextLabel: 'Отправил' }, { status: 'sent', label: 'Отправлено', next: 'interview', nextLabel: 'Интервью' }, { status: 'interview', label: 'Интервью', next: 'result', nextLabel: 'В результат' }, { status: 'result', label: 'Результат' }];
const statusLabels: Record<Status, string> = { saved: 'Сохранено', sent: 'Отправлено', interview: 'Интервью', result: 'Результат', archived: 'Архив' };
const eventLabels: Record<EventType, string> = { saved: 'Сохранено', applied: 'Отклик отправлен', hr_screening: 'HR screening', interview: 'Technical interview', final_interview: 'Final interview', follow_up: 'Follow-up', result: 'Результат' };
const interviewStages: Array<{ stage: InterviewStage; label: string }> = [{ stage: 'hr_screening', label: 'HR screening' }, { stage: 'interview', label: 'Technical interview' }, { stage: 'final_interview', label: 'Final interview' }, { stage: 'follow_up', label: 'Follow-up' }];
const stageColors: Record<Exclude<Status, 'archived'>, { column: string; heading: string; count: string; empty: string }> = {
  saved: { column: 'border-slate-200 bg-slate-100', heading: 'text-slate-700', count: 'bg-slate-200 text-slate-700', empty: 'border-slate-300 text-slate-500' },
  sent: { column: 'border-blue-200 bg-blue-50', heading: 'text-blue-800', count: 'bg-blue-200 text-blue-800', empty: 'border-blue-200 text-blue-700' },
  interview: { column: 'border-violet-200 bg-violet-50', heading: 'text-violet-800', count: 'bg-violet-200 text-violet-800', empty: 'border-violet-200 text-violet-700' },
  result: { column: 'border-emerald-200 bg-emerald-50', heading: 'text-emerald-800', count: 'bg-emerald-200 text-emerald-800', empty: 'border-emerald-200 text-emerald-700' }
};
type ViewState = { mode: 'table' | 'board'; search: string; status: string; source: string; tag: string; sort: SortBy; group: GroupBy; archive: boolean };
const viewStorageKey = 'job-tracker.view-state-v2';
const validSorts = new Set<SortBy>(['newest', 'oldest', 'updated', 'company', 'location', 'title', 'waiting']);
const validGroups = new Set<GroupBy>(['', 'tag', 'company', 'location', 'source', 'month']);
const storedView = (() => { try { return JSON.parse(localStorage.getItem(viewStorageKey) ?? '{}') as Partial<ViewState>; } catch { return {}; } })();
const urlView = new URLSearchParams(location.search);
const viewState: ViewState = {
  mode: urlView.get('view') === 'table' || (!urlView.get('view') && storedView.mode === 'table') ? 'table' : 'board',
  search: urlView.get('q') ?? storedView.search ?? '', status: urlView.get('status') ?? storedView.status ?? '', source: urlView.get('source') ?? storedView.source ?? '', tag: urlView.get('tag') ?? storedView.tag ?? '',
  sort: validSorts.has(urlView.get('sort') as SortBy) ? urlView.get('sort') as SortBy : validSorts.has(storedView.sort as SortBy) ? storedView.sort as SortBy : 'newest',
  group: validGroups.has(urlView.get('group') as GroupBy) ? urlView.get('group') as GroupBy : validGroups.has(storedView.group as GroupBy) ? storedView.group as GroupBy : '',
  archive: urlView.get('archive') === '1' || (!urlView.has('archive') && Boolean(storedView.archive))
};
let current: Job | null = null; let matchSubject: Job | null = null; let jobs: Job[] = []; let mode: 'table' | 'board' = viewState.mode; let archiveMode = viewState.archive; let aiConnections: AiConnection[] = []; let allTags: Tag[] = [];
const $ = <T extends HTMLElement>(selector: string) => document.querySelector(selector) as T;
const escape = (value: string | null) => (value ?? '—').replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[character]!));
const show = (message: string, failure = false) => { const notice = $('#notice'); const text = document.createElement('span'); text.textContent = message; const close = document.createElement('button'); close.type = 'button'; close.className = '-m-1 shrink-0 rounded p-1 text-lg leading-none opacity-70 hover:bg-black/10 hover:opacity-100'; close.setAttribute('aria-label', 'Скрыть уведомление'); close.textContent = '×'; close.onclick = () => notice.classList.add('hidden'); notice.replaceChildren(text, close); notice.className = `fixed right-4 top-4 z-50 flex max-w-md items-start gap-3 rounded-lg p-4 pr-3 text-sm shadow-lg ${failure ? 'bg-red-50 text-red-800' : 'bg-blue-50 text-blue-800'}`; };
const formatDate = (value: string) => new Date(value).toLocaleDateString('ru-RU', { day: '2-digit', month: 'short', year: 'numeric' });
const formatDateTime = (value: string) => new Date(value).toLocaleString('ru-RU', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const dateForInput = () => { const date = new Date(); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); };
const ageDays = (job: Job) => Math.floor((Date.now() - new Date(job.last_event_at || job.created_at).getTime()) / 86_400_000);
const ageTone = (job: Job) => ageDays(job) >= 35 ? 'red' : ageDays(job) >= 14 ? 'yellow' : 'normal';
const ageBadge = (job: Job) => { const days = ageDays(job); if (days < 14) return ''; const tone = ageTone(job); return `<span class="rounded px-2 py-1 text-xs font-medium ${tone === 'red' ? 'bg-red-100 text-red-800' : 'bg-yellow-100 text-yellow-800'}">${days} дн. без события</span>`; };
const tableAgeBadge = (job: Job) => { const days = ageDays(job); const tone = ageTone(job); if (tone === 'red') return `<span class="inline-flex rounded-full bg-red-100 px-2.5 py-1 text-xs font-semibold text-red-800">${days} дн. без события</span>`; if (tone === 'yellow') return `<span class="inline-flex rounded-full bg-yellow-100 px-2.5 py-1 text-xs font-semibold text-yellow-800">${days} дн. без события</span>`; return `<span class="text-xs text-gray-500">${days ? `${days} дн.` : 'Сегодня'}</span>`; };
const tableStatusBadge = (status: Status) => { const colors: Record<Status, string> = { saved: 'bg-slate-200 text-slate-700', sent: 'bg-blue-100 text-blue-800', interview: 'bg-violet-100 text-violet-800', result: 'bg-emerald-100 text-emerald-800', archived: 'bg-amber-100 text-amber-800' }; return `<span class="rounded-full px-2.5 py-1 text-xs font-semibold ${colors[status]}">${statusLabels[status]}</span>`; };
async function api(url: string, init?: RequestInit) { const response = await fetch(url, { headers: { 'content-type': 'application/json', ...(init?.headers ?? {}) }, ...init }); if (!response.ok && response.status !== 204) { const payload = await response.json().catch(() => ({ error: response.statusText })) as { error?: string; details?: { fieldErrors?: Record<string, string[]>; formErrors?: string[] } }; const details = [...Object.values(payload.details?.fieldErrors ?? {}).flat(), ...(payload.details?.formErrors ?? [])]; throw new Error(details.length ? `${payload.error ?? response.statusText}: ${details.join(', ')}` : payload.error ?? response.statusText); } return response.status === 204 ? undefined : response.json(); }
function syncViewState() { viewState.mode = mode; viewState.archive = archiveMode; localStorage.setItem(viewStorageKey, JSON.stringify(viewState)); const params = new URLSearchParams(); if (viewState.mode !== 'board') params.set('view', viewState.mode); if (viewState.search) params.set('q', viewState.search); if (viewState.status) params.set('status', viewState.status); if (viewState.source) params.set('source', viewState.source); if (viewState.tag) params.set('tag', viewState.tag); if (viewState.sort !== 'newest') params.set('sort', viewState.sort); if (viewState.group) params.set('group', viewState.group); if (viewState.archive) params.set('archive', '1'); history.replaceState(null, '', `${location.pathname}${params.size ? `?${params}` : ''}`); }
function query() { const params = new URLSearchParams(); if (viewState.search) params.set('search', viewState.search); if (viewState.status) params.set('status', viewState.status); if (viewState.source) params.set('source', viewState.source); if (viewState.tag) params.set('tag', viewState.tag); params.set('order', viewState.sort); if (archiveMode) params.set('archive', 'only'); return params; }
async function loadJobs() { syncViewState(); const [loadedJobs, tags] = await Promise.all([api(`/api/jobs?${query()}`) as Promise<Job[]>, api('/api/tags') as Promise<Tag[]>]); jobs = loadedJobs; allTags = tags; render(); renderViewControls(); }
function render() { $('#view-summary').textContent = archiveMode ? `${jobs.length} в архиве` : `${jobs.length} активных вакансий`; $('#archive-toggle').setAttribute('title', archiveMode ? 'К активным вакансиям' : 'Архив'); $('#archive-toggle').setAttribute('aria-label', archiveMode ? 'К активным вакансиям' : 'Архив'); $('#table-view').classList.toggle('hidden', !archiveMode && mode !== 'table'); $('#board-view').classList.toggle('hidden', archiveMode || mode !== 'board'); $('#table-mode').className = mode === 'table' ? 'rounded-lg bg-blue-700 p-2.5 text-white' : 'rounded-lg border border-gray-300 bg-white p-2.5 hover:bg-gray-50'; $('#board-mode').className = mode === 'board' ? 'rounded-lg bg-blue-700 p-2.5 text-white' : 'rounded-lg border border-gray-300 bg-white p-2.5 hover:bg-gray-50'; $('#table-mode').classList.toggle('hidden', archiveMode); $('#board-mode').classList.toggle('hidden', archiveMode); renderTable(); if (!archiveMode) renderBoard(); }
function renderTable() { const body = $('#jobs'); body.innerHTML = jobs.length ? jobs.map(job => { const tone = ageTone(job); const row = tone === 'red' ? 'bg-red-50 hover:bg-red-100' : tone === 'yellow' ? 'bg-yellow-50 hover:bg-yellow-100' : 'bg-white hover:bg-gray-50'; const accent = tone === 'red' ? 'border-l-4 border-red-500' : tone === 'yellow' ? 'border-l-4 border-yellow-400' : 'border-l-4 border-transparent'; return `<tr class="cursor-pointer ${row}" data-open="${job.id}"><td class="${accent} px-5 py-4 font-medium text-gray-900">${escape(job.company)}</td><td class="px-5 py-4 font-medium text-gray-900">${escape(job.title)}${tagPills(job.tags)}</td><td class="px-5 py-4">${escape(job.location)}</td><td class="px-5 py-4">${tableStatusBadge(job.status)}</td><td class="px-5 py-4">${tableAgeBadge(job)}</td><td class="px-5 py-4 whitespace-nowrap">${formatDate(job.created_at)}</td><td class="px-5 py-4">${archiveMode ? '<button data-unarchive="' + job.id + '" class="rounded border border-gray-300 px-2 py-1 text-xs font-medium hover:bg-gray-50">Вернуть</button>' : '<button data-archive="' + job.id + '" class="rounded border border-amber-300 px-2 py-1 text-xs font-medium text-amber-800 hover:bg-amber-50">Архив</button>'}</td></tr>`; }).join('') : '<tr><td colspan="7" class="px-5 py-10 text-center text-gray-500">Вакансий нет.</td></tr>'; bindJobActions(body); }
function matchIndicator(job: Job) { const match = job.ai_match; if (!match) return `<button data-match-modal="${job.id}" aria-label="AI: анализ не выполнялся" class="group relative block rounded-full p-1"><span class="block h-2.5 w-2.5 rounded-full bg-gray-400"></span><span role="tooltip" class="pointer-events-none absolute right-0 top-6 z-20 w-56 rounded-lg bg-gray-900 p-3 text-left text-xs font-normal text-white opacity-0 shadow-lg transition-opacity group-hover:opacity-100 group-focus:opacity-100">AI-анализ ещё не выполнялся. Нажмите, чтобы открыть.</span></button>`; const labels: Record<MatchClassification, [string, string]> = { strong: ['Сильное соответствие', 'bg-emerald-500'], potential: ['Частичное соответствие', 'bg-amber-500'], weak: ['Существенные несоответствия', 'bg-red-500'], insufficient_data: ['Недостаточно данных', 'bg-gray-400'] }; const [label, color] = match.outdated ? ['Результат устарел', 'bg-slate-500'] : labels[match.classification]; const counts = match.result.requirements.reduce((result, item) => ({ ...result, [item.status]: (result[item.status] ?? 0) + 1 }), {} as Record<string, number>); return `<button data-match-modal="${job.id}" aria-label="AI: ${label}" class="group relative block rounded-full p-1"><span class="block h-2.5 w-2.5 rounded-full ${color}"></span><span role="tooltip" class="pointer-events-none absolute right-0 top-6 z-20 w-64 rounded-lg bg-gray-900 p-3 text-left text-xs font-normal text-white opacity-0 shadow-lg transition-opacity group-hover:opacity-100 group-focus:opacity-100"><strong class="block text-sm">${label}</strong><span class="mt-1 block text-gray-200">${escape(match.result.summary)}</span><span class="mt-2 block text-gray-300">${counts.confirmed ?? 0} подтверждено · ${counts.partial ?? 0} частично · ${counts.not_evidenced ?? 0} без доказательств</span><span class="mt-1 block text-gray-400">${formatDateTime(match.completed_at)} · ${escape(match.model)}</span></span></button>`; }
const tagColorPalette = ['#1d4ed8', '#047857', '#9f1239', '#7e22ce', '#0f766e', '#b45309', '#4338ca', '#be123c'];
const randomTagColor = () => tagColorPalette[Math.floor(Math.random() * tagColorPalette.length)];
const tagPill = (tag: Tag) => `<span class="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium" style="background:${escape(tag.color)}1f;color:${escape(tag.color)}"><span class="h-1.5 w-1.5 rounded-full" style="background:${escape(tag.color)}"></span>${escape(tag.name)}</span>`;
const removableTagPill = (tag: Tag) => `<button type="button" data-remove-job-tag="${tag.id}" aria-label="Убрать тег ${escape(tag.name)}" class="group inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium transition-opacity hover:opacity-80" style="background:${escape(tag.color)}1f;color:${escape(tag.color)}"><span class="relative h-2.5 w-2.5"><span class="absolute inset-0 rounded-full group-hover:hidden" style="background:${escape(tag.color)}"></span><span class="absolute -top-1 left-0 hidden text-sm leading-none group-hover:block">×</span></span>${escape(tag.name)}</button>`;
const tagPills = (tags: Tag[]) => tags.length ? `<div class="mt-2 flex flex-wrap gap-1">${tags.map(tagPill).join('')}</div>` : '';
function card(job: Job, stage: typeof stages[number]) { const tone = ageTone(job); return `<article draggable="true" data-drag-job="${job.id}" class="relative cursor-grab rounded-lg border bg-white p-3 shadow-sm active:cursor-grabbing ${tone === 'red' ? 'border-red-300' : tone === 'yellow' ? 'border-yellow-300' : 'border-gray-200'}"><div class="absolute right-2 top-2">${matchIndicator(job)}</div><button data-open="${job.id}" class="block w-full pr-5 text-left"><p class="text-sm font-semibold text-gray-900">${escape(job.title)}</p><p class="mt-1 text-sm text-gray-600">${escape(job.company)}</p><p class="mt-1 text-xs text-gray-500">${escape(job.location)} · ${formatDate(job.created_at)}</p>${tagPills(job.tags)}</button><div class="mt-3 flex items-center justify-between gap-2">${ageBadge(job)}</div><div class="mt-3 flex justify-end gap-1">${stage.next ? `<button data-stage="${job.id}" data-status="${stage.next}" class="rounded bg-blue-700 px-2 py-1 text-xs font-medium text-white hover:bg-blue-800">${stage.nextLabel}</button>` : ''}<button data-archive="${job.id}" class="rounded border border-amber-300 px-2 py-1 text-xs font-medium text-amber-800 hover:bg-amber-50">Архив</button></div></article>`; }
function boardColumns(groupJobs: Job[]) { return `<div class="grid w-full grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">${stages.map(stage => { const stageJobs = groupJobs.filter(job => job.status === stage.status); const colors = stageColors[stage.status]; return `<section data-drop-status="${stage.status}" class="min-h-64 rounded-lg border p-3 transition-shadow ${colors.column}"><div class="mb-1 flex items-center justify-between"><h2 class="font-semibold ${colors.heading}">${stage.label}</h2><span class="rounded px-2 py-1 text-xs font-medium ${colors.count}">${stageJobs.length}</span></div><p class="mb-3 text-xs text-gray-500">Перетащите карточку сюда</p><div class="space-y-3">${stageJobs.map(job => card(job, stage)).join('') || `<p class="rounded border border-dashed p-4 text-center text-sm ${colors.empty}">Пока пусто</p>`}</div></section>`; }).join('')}</div>`; }
function boardGroups() { if (!viewState.group) return [{ label: '', jobs }]; const buckets = new Map<string, Job[]>(); const add = (label: string, job: Job) => buckets.set(label, [...(buckets.get(label) ?? []), job]); for (const job of jobs) { if (viewState.group === 'tag') { if (job.tags.length) job.tags.forEach(tag => add(tag.name, job)); else add('Без тегов', job); } else if (viewState.group === 'company') add(job.company || 'Без компании', job); else if (viewState.group === 'location') add(job.location || 'Без локации', job); else if (viewState.group === 'source') add(job.source || 'Другой источник', job); else add(new Intl.DateTimeFormat('ru-RU', { month: 'long', year: 'numeric' }).format(new Date(job.created_at)), job); } return [...buckets.entries()].sort(([left], [right]) => left.localeCompare(right, 'ru')).map(([label, groupJobs]) => ({ label, jobs: groupJobs })); }
function renderBoard() { const board = $('#board'); const groups = boardGroups(); board.className = viewState.group ? 'w-full space-y-8' : 'w-full'; board.innerHTML = groups.map(group => viewState.group ? `<section><div class="mb-3 flex items-center gap-3"><h2 class="text-base font-semibold text-gray-900">${escape(group.label)}</h2><span class="rounded-full bg-gray-100 px-2 py-0.5 text-xs text-gray-600">${group.jobs.length}</span></div>${boardColumns(group.jobs)}</section>` : boardColumns(group.jobs)).join('') || '<p class="py-10 text-center text-sm text-gray-500">Вакансий нет.</p>'; bindJobActions(board); }
function bindJobActions(container: HTMLElement) { container.querySelectorAll<HTMLElement>('[data-open]').forEach(button => button.onclick = () => void openJob(button.dataset.open!)); container.querySelectorAll<HTMLElement>('[data-match-modal]').forEach(button => button.onclick = event => { event.stopPropagation(); void openMatchDialog(button.dataset.matchModal!).catch(error => show(error.message, true)); }); container.querySelectorAll<HTMLElement>('[data-stage]').forEach(button => button.onclick = event => { event.stopPropagation(); void setStatus(button.dataset.stage!, button.dataset.status as Status); }); container.querySelectorAll<HTMLElement>('[data-archive]').forEach(button => button.onclick = event => { event.stopPropagation(); void setStatus(button.dataset.archive!, 'archived'); }); container.querySelectorAll<HTMLElement>('[data-unarchive]').forEach(button => button.onclick = event => { event.stopPropagation(); void setStatus(button.dataset.unarchive!, 'saved'); }); container.querySelectorAll<HTMLElement>('[data-drag-job]').forEach(item => { item.addEventListener('dragstart', event => { event.dataTransfer?.setData('text/plain', item.dataset.dragJob!); if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move'; item.classList.add('opacity-50'); }); item.addEventListener('dragend', () => { item.classList.remove('opacity-50'); container.querySelectorAll<HTMLElement>('[data-drop-status]').forEach(column => column.classList.remove('ring-2', 'ring-blue-300')); }); }); container.querySelectorAll<HTMLElement>('[data-drop-status]').forEach(column => { column.addEventListener('dragover', event => { event.preventDefault(); if (event.dataTransfer) event.dataTransfer.dropEffect = 'move'; column.classList.add('ring-2', 'ring-blue-300'); }); column.addEventListener('dragleave', () => column.classList.remove('ring-2', 'ring-blue-300')); column.addEventListener('drop', event => { event.preventDefault(); column.classList.remove('ring-2', 'ring-blue-300'); const id = event.dataTransfer?.getData('text/plain'); const status = column.dataset.dropStatus as Status | undefined; if (id && status && jobs.find(job => job.id === id)?.status !== status) void setStatus(id, status); }); }); }
function renderMatch(match: AiMatch | null | undefined) { const target = $('#match-analysis'); if (!match) { target.textContent = 'Анализ ещё не выполнен.'; return; } const labels: Record<MatchClassification, string> = { strong: 'Сильное соответствие', potential: 'Частичное соответствие', weak: 'Слабое соответствие', insufficient_data: 'Недостаточно данных' }; target.innerHTML = `<p class="font-medium text-gray-900">${labels[match.classification]}${match.outdated ? ' · требуется повторный анализ' : ''}</p><p class="mt-1 text-gray-600">${escape(match.result.summary)}</p><p class="mt-2 text-xs text-gray-500">${formatDateTime(match.completed_at)} · ${escape(match.model)}</p><h4 class="mt-3 font-medium text-gray-800">Требования</h4><ul class="mt-1 space-y-2">${match.result.requirements.map(item => `<li><span class="font-medium">${escape(item.requirement)}</span> — ${escape(item.status)}${item.evidenceIds.length ? ` · ${escape(item.evidenceIds.join(', '))}` : ''}</li>`).join('')}</ul>${match.result.eligibility.length ? `<h4 class="mt-3 font-medium text-gray-800">Eligibility</h4><ul class="mt-1 space-y-2">${match.result.eligibility.map(item => `<li><span class="font-medium">${escape(item.criterion)}</span> — ${escape(item.status)}</li>`).join('')}</ul>` : ''}`; }
const matchDialog = () => $('#match-dialog') as HTMLDialogElement;
const jobEditDialog = () => $('#job-edit-dialog') as HTMLDialogElement;
async function openMatchDialog(id: string) { matchSubject = current?.id === id ? current : jobs.find(job => job.id === id) ?? await api(`/api/jobs/${id}`) as Job; $('#match-dialog-title').textContent = matchSubject.title ?? 'Без названия'; $('#match-dialog-company').textContent = matchSubject.company ?? 'Неизвестная компания'; renderMatch(matchSubject.ai_match); if (!matchDialog().open) matchDialog().showModal(); }
let aiSettings: AiSettings = { default_connection_id: null, default_model: null }; let profileSummary: ProfileSummary = { configured: false };
const aiDialog = () => document.querySelector('#ai-provider-dialog') as HTMLDialogElement | null;
