type ApplicationStats = { from: string | null; to: string; first_day: string | null; total: number; days: Array<{ day: string; count: number }> };
type ApplicationStatsScale = 'day' | 'week' | 'month' | 'all';
const applicationStatsStorageKey = 'job-tracker.application-stats-scale';
const dateKey = (date: Date) => date.toISOString().slice(0, 10);
const applicationStatsScale = (): ApplicationStatsScale => { const saved = localStorage.getItem(applicationStatsStorageKey); return saved === 'day' || saved === 'week' || saved === 'month' || saved === 'all' ? saved : 'week'; };
const dateFromKey = (day: string) => new Date(`${day}T00:00:00.000Z`);
const localDateKey = (date: Date) => { const local = new Date(date); local.setMinutes(local.getMinutes() - local.getTimezoneOffset()); return dateKey(local); };
function applicationStatsRange(scale: ApplicationStatsScale) { if (scale === 'all') return null; const end = new Date(); const start = new Date(end); start.setDate(start.getDate() - (scale === 'day' ? 0 : scale === 'week' ? 6 : 29)); return { from: localDateKey(start), to: localDateKey(end) }; }
