function setApplicationStatsScale(scale: ApplicationStatsScale) { localStorage.setItem(applicationStatsStorageKey, scale); document.querySelectorAll<HTMLButtonElement>('[data-application-stats-scale]').forEach(button => { const active = button.dataset.applicationStatsScale === scale; button.classList.toggle('bg-blue-700', active); button.classList.toggle('text-white', active); button.classList.toggle('border-blue-700', active); button.classList.toggle('border-gray-300', !active); button.classList.toggle('bg-white', !active); button.classList.toggle('text-gray-700', !active); }); }
